mapper.select:
SELECT uf.id AS follow_id, uf.user_id AS user_id, uf.lecturer_id AS lecturer_id, uf.follow_time AS follow_time, l.main_account_id AS main_account_id, l.course_count AS course_count, l.follow_count AS follow_count, l.personal_intro AS personal_intro, l.cover_image_url AS cover_image_url, l.avatar_url AS avatar_url, c.name AS lecturer_name, c.username AS main_account, c.head_img AS channel_head_img, lc.id AS category_id, lc.category_name AS category_name FROM user_lecturer_follow uf LEFT JOIN lecturer l ON uf.lecturer_id = l.id AND l.is_deleted = 0 LEFT JOIN channel c ON l.main_account_id = c.id LEFT JOIN lecturer_category lc ON lc.id = l.lecturer_category_id WHERE uf.is_deleted = 0 AND uf.user_id = #{req.userId}
AND c.name LIKE CONCAT('%', #{req.lecturerName}, '%')
ORDER BY uf.follow_time DESC
